<?php
namespace CmuLms;
final class Attendance extends Model {public static function forCourse(int $course,bool $includeClosed=false,?int $limit=null,int $offset=0):array{$includeClosed=$includeClosed||(($_SESSION['user']['role']??'')!=='student');$sql='SELECT * FROM attendance_sessions WHERE course_id=? '.($includeClosed?'':'AND is_enabled=1').' ORDER BY opens_at DESC';$params=[$course];if($limit!==null){$sql.=' LIMIT '.max(1,$limit).' OFFSET '.max(0,$offset);}return self::all($sql,$params);}public static function countForCourse(int $course,bool $includeClosed=false):int{$includeClosed=$includeClosed||(($_SESSION['user']['role']??'')!=='student');return (int)self::one('SELECT COUNT(*) total FROM attendance_sessions WHERE course_id=? '.($includeClosed?'':'AND is_enabled=1'),[$course])['total'];}public static function studentSummary(int $course,int $student):array{return self::all('SELECT a.id,a.title,a.opens_at,a.closes_at,s.status,s.submitted_at FROM attendance_sessions a LEFT JOIN attendance_submissions s ON s.session_id=a.id AND s.student_id=? WHERE a.course_id=? AND a.is_enabled=1 ORDER BY a.opens_at DESC',[$student,$course]);}public static function roster(int $id):array{return self::all('SELECT s.id,u.name,u.id_number,s.status,s.submitted_at,s.photo_path FROM users u JOIN enrollments e ON e.user_id=u.id AND e.status="active" LEFT JOIN attendance_submissions s ON s.student_id=u.id AND s.session_id=? WHERE e.course_id=(SELECT course_id FROM attendance_sessions WHERE id=?) AND u.role="student" ORDER BY u.last_name,u.name',[$id,$id]);}}
